{"code": "from PIL import Image
import os

def check_corrupted(folder):
    files = os.listdir(folder)
    corrupted = []
    for f in files:
        filepath = os.path.join(folder, f)
        try:
            img = Image.open(filepath)
            img.verify()  # Verify if it's a valid image
            img.close()
        except Exception as e:
            corrupted.append((f, str(e)))
    return corrupted

corrupted_chic = check_corrupted('data_small/Chic')
corrupted_duck = check_corrupted('data_small/Duck')

print(f"Corrupted Chic files: {len(corrupted_chic)}")
for f, err in corrupted_chic[:5]:
    print(f"  {f}: {err}")

print(f"\nCorrupted Duck files: {len(corrupted_duck)}")
for f, err in corrupted_duck[:5]:
    print(f"  {f}: {err}")"}

